export const PUBLIC_SKILL_SLUGS = PUBLIC_SKILLS.map((s) => s.slug);

export function getPublicSkill(slug: string): PublicSkill | undefined {
  return PUBLIC_SKILLS.find((s) => s.slug === slug);
}
